begin;
create extension if not exists pgtap with schema extensions;
select extensions.no_plan();



-- Exact launch-acceptance stream: the baseline is an event, but has no usage.

-- A linked reading in August owns its delta even when its previous effective value is in July.

-- A superseded value, its effective correction, a following value, and a voided duplicate.

-- Makassar month boundaries: 16:00 UTC is local midnight.

set local role authenticated;
select set_config('request.jwt.claim.sub','c0000000-0000-4000-8000-000000000001',true);

select extensions.is((select total_clicks from public.get_machine_cost_period('c0100000-0000-4000-8000-000000000001','c0400000-0000-4000-8000-000000000001','2026-08-01','2026-08-31')),1709::numeric,'August sums 628 plus 1081 without an August 1 boundary reading');
select extensions.is((select total_clicks from public.get_machine_cost_period('c0100000-0000-4000-8000-000000000001','c0400000-0000-4000-8000-000000000001','2026-08-27','2026-08-27')),1081::numeric,'custom period attributes usage to the effective reading event date');
select extensions.is((select total_clicks from public.get_machine_cost_period('c0100000-0000-4000-8000-000000000001','c0400000-0000-4000-8000-000000000001','2026-08-26','2026-08-26')),628::numeric,'multiple same-day readings include baseline zero and the later delta');
select extensions.is((select total_clicks from public.get_machine_cost_period('c0100000-0000-4000-8000-000000000001','c0400000-0000-4000-8000-000000000002','2026-08-01','2026-08-31')),0::numeric,'a period containing only a baseline has valid zero accumulated usage');
select extensions.is((select counter_status::text from public.get_machine_cost_period('c0100000-0000-4000-8000-000000000001','c0400000-0000-4000-8000-000000000002','2026-08-01','2026-08-31')),'COMPLETE','baseline-only counter evidence is complete');
select extensions.ok((select total_clicks is null from public.get_machine_cost_period('c0100000-0000-4000-8000-000000000001','c0400000-0000-4000-8000-000000000003','2026-08-01','2026-08-31')),'no in-period counter evidence remains null rather than fabricated zero');
select extensions.is((select counter_status::text from public.get_machine_cost_period('c0100000-0000-4000-8000-000000000001','c0400000-0000-4000-8000-000000000003','2026-08-01','2026-08-31')),'NO_DATA','no in-period counter evidence reports NO_DATA');
select extensions.is((select total_clicks from public.get_machine_cost_period('c0100000-0000-4000-8000-000000000001','c0400000-0000-4000-8000-000000000006','2026-08-01','2026-08-31')),400::numeric,'a current-month reading retains authoritative usage linked to the previous-month effective value');
select extensions.is((select total_clicks from public.get_machine_cost_period('c0100000-0000-4000-8000-000000000001','c0400000-0000-4000-8000-000000000006','2026-08-01','2026-08-01')),400::numeric,'zero-usage readings remain valid and add zero to accumulated usage');
select extensions.is((select total_clicks from public.get_machine_cost_period('c0100000-0000-4000-8000-000000000001','c0400000-0000-4000-8000-000000000004','2026-08-01','2026-08-31')),600::numeric,'only effective correction history contributes: 500 correction plus 100 next usage');
select extensions.is((select total_clicks from public.get_machine_cost_period('c0100000-0000-4000-8000-000000000001','c0400000-0000-4000-8000-000000000005','2026-08-01','2026-08-31')),50::numeric,'resolved Asia/Makassar month includes local August events and excludes adjacent boundaries');
select extensions.is((select resolved_timezone from public.get_machine_cost_period('c0100000-0000-4000-8000-000000000001','c0400000-0000-4000-8000-000000000005','2026-08-01','2026-08-31')),'Asia/Makassar','branch timezone resolves when machine timezone is absent');
select extensions.is((select total_clicks from public.get_machine_economics_period('c0100000-0000-4000-8000-000000000001','c0400000-0000-4000-8000-000000000001','2026-08-01','2026-08-31')),1709::numeric,'economics contract reuses corrected database-authoritative period clicks');

select * from extensions.finish();
rollback;
